from pathlib import Path
import json,hashlib,sys
ROOT=Path(__file__).resolve().parents[3]
OUT=Path(__file__).resolve().parent
baseline=json.loads((OUT/'baseline.json').read_text(encoding='utf-8'))
texts={}; changes=[]
def md(d):return f'content/isc2-cc-2026/reading/domain-{d}.md'
def sc(d):return f'content/isc2-cc-2026/reading/domain-{d}-scenarios.js'
G='js/core/diagram-generator.js'; C='js/core/content-components.js'
def source(f):
 if f not in texts:
  b=(ROOT/f).read_bytes();assert hashlib.sha256(b).hexdigest()==baseline['hashes'][f],f'Concurrent change: {f}'
  texts[f]=b.decode('utf-8')
 return texts[f]
def swap(id,f,old,new,count=1):
 s=source(f);assert s.count(old)==count,(id,f,old,s.count(old),count)
 changes.append(dict(id=id,file=f,before=old,after=new,count=count))
 texts[f]=s.replace(old,new)
def line(id,f,needle,new):
 matches=[x for x in source(f).splitlines() if needle in x]
 assert len(matches)==1,(id,f,needle,len(matches))
 old=matches[0];indent=old[:len(old)-len(old.lstrip())]
 swap(id,f,old,indent+new)

